select c.class_name, count(u.user_id) classUserCount from sys_user u,ms_class c where u.class_id=c.class_id and u.del_flag='0' and u.class_id in
#{classId}
group by u.class_id

select c.class_name, count(tc.class_id) classTestCount from ms_test_class tc,ms_class c where tc.class_id=c.class_id and tc.del_flag='0' and tc.class_id in
#{classId}
group by tc.class_id
